// batch79: consoleObservableLogger + debugGetDependencyGraph — data-driven from
// batch79_truth.json (truth generated by Node vm against the real TS sources).
import 'dart:convert';
import 'dart:io';

import 'package:flutter_test/flutter_test.dart';
import 'package:semi_design_flutter/src/monaco/base/common/observableInternal/debugName.dart'
    show cachedDebugName, countPerName, ownerId, countPerClassName;
import 'package:semi_design_flutter/src/monaco/base/common/observableInternal/logging/consoleObservableLogger.dart'
    as cl;
import 'package:semi_design_flutter/src/monaco/base/common/observableInternal/logging/debugGetDependencyGraph.dart'
    as dg;
import 'package:semi_design_flutter/src/monaco/base/common/observableInternal/logging/logging.dart'
    show IChangeInformation;
import 'package:semi_design_flutter/src/monaco/base/common/observableInternal/observables/derived.dart'
    as d;
import 'package:semi_design_flutter/src/monaco/base/common/observableInternal/observables/observableValue.dart'
    as ov;
import 'package:semi_design_flutter/src/monaco/base/common/observableInternal/reactions/autorun.dart'
    as au;

Map<String, dynamic> _truth() => jsonDecode(
      File('tool/ts2dart/batch79_truth.json').readAsStringSync(),
    ) as Map<String, dynamic>;

class _CustomToString {
  @override
  String toString() => 'CustomObj';
}

void _resetDebugNames() {
  cachedDebugName.clear();
  countPerName.clear();
  ownerId.clear();
  countPerClassName.clear();
}

class _Captured {
  final format = <String>[];
  final rest = <List<Object?>>[];
}

void main() {
  group('batch79 formatValue', () {
    test('all value kinds', () {
      final t = _truth()['formatValue'] as Map<String, dynamic>;
      expect(cl.formatValue(42, 60), t['number']);
      expect(cl.formatValue(-7, 60), t['negative']);
      expect(cl.formatValue('hello', 60), t['shortString']);
      expect(cl.formatValue('abcdefghijklmnopqrstuvwxyz0123456789', 10),
          t['longString']);
      expect(cl.formatValue(true, 60), t['boolTrue']);
      expect(cl.formatValue(false, 60), t['boolFalse']);
      expect(cl.formatValue(null, 60), t['undefined']);
      expect(cl.formatValue(<Object?>[1, 'a', true], 60), t['array']);
      expect(cl.formatValue(<Object?>[1, 2, 3, 4, 5, 6, 7], 12),
          t['arrayTruncated']);
      expect(cl.formatValue(_CustomToString(), 60), t['object']);
    });
  });

  group('batch79 ConsoleObservableLogger', () {
    test('observable value update lines', () {
      final t = _truth()['loggerUpdates'] as Map<String, dynamic>;
      final captured = _Captured();
      cl.consoleLog = (format, rest) {
        captured.format.add(format as String);
        captured.rest.add(rest);
      };
      _resetDebugNames();
      final logger = cl.ConsoleObservableLogger();
      final o = ov.observableValue<int, Object?>('counter', 1);
      logger.handleObservableCreated(o, null);
      logger.handleObservableUpdated(o, IChangeInformation(
        hadValue: false, newValue: 5, oldValue: null, change: null, didChange: true));
      logger.handleObservableUpdated(o, IChangeInformation(
        hadValue: true, newValue: 9, oldValue: 5, change: null, didChange: true));
      logger.handleObservableUpdated(o, IChangeInformation(
        hadValue: true, newValue: 9, oldValue: 9, change: null, didChange: false));
      final lines = <String>[];
      for (int i = 0; i < captured.format.length; i++) {
        lines.add([captured.format[i], ...captured.rest[i]]
            .map((a) => a is String ? a : jsonEncode(a))
            .join(' | '));
      }
      expect(lines, t['lines']);
      expect(lines.length, t['count']);
    });

    test('filtered objects', () {
      final t = _truth()['loggerFilter'] as Map<String, dynamic>;
      final captured = _Captured();
      cl.consoleLog = (format, rest) {
        captured.format.add(format as String);
        captured.rest.add(rest);
      };
      _resetDebugNames();
      final filtered = cl.ConsoleObservableLogger();
      final o = ov.observableValue<int, Object?>('counter', 1);
      filtered.addFilteredObj(o);
      final other = ov.observableValue<int, Object?>('other', 1);
      filtered.handleObservableUpdated(other, IChangeInformation(
        hadValue: false, newValue: 1, oldValue: null, change: null, didChange: true));
      filtered.handleObservableUpdated(o, IChangeInformation(
        hadValue: true, newValue: 2, oldValue: 1, change: null, didChange: true));
      final lines = <String>[];
      for (int i = 0; i < captured.format.length; i++) {
        lines.add([captured.format[i], ...captured.rest[i]]
            .map((a) => a is String ? a : jsonEncode(a))
            .join(' | '));
      }
      expect(lines, t['lines']);
      expect(lines.length, t['count']);
    });
  });

  group('batch79 debugGetObservableGraph', () {
    test('dependencies / observers / postprocessor / unknown', () {
      final t = _truth()['graph'] as Map<String, dynamic>;
      final src = ov.observableValue<int, Object?>('src', 1);
      final mid = d.derived<int, Object?>((reader) => reader.readObservable(src) * 2);
      final seen = <int>[];
      final dd = au.autorun((reader) => seen.add(mid.read(reader)));
      expect(
          dg.debugGetObservableGraph(
              mid, dg.GraphOptions(type: 'dependencies')),
          t['depsGraph']);
      expect(
          dg.debugGetObservableGraph(
              src, dg.GraphOptions(type: 'observers')),
          t['obsGraph']);
      expect(
          dg.debugGetObservableGraph(
            mid,
            dg.GraphOptions(
                type: 'dependencies',
                debugNamePostProcessor: (n) => 'X-$n'),
          ),
          t['ppGraph']);
      expect(
          dg.debugGetObservableGraph(
              <String, Object?>{'debugName': 'fake'},
              dg.GraphOptions(type: 'dependencies')),
          t['unknownGraph']);
      dd.dispose();
    });
  });
}
